#include <iostream>
#include <vector>

using namespace std;

const int M = 1000000007;
long long n;
vector<vector<int>> m, st;

vector<vector<int>> pr(const vector<vector<int>>& a,
                       const vector<vector<int>>& b)
{
    vector<vector<int>> r(2, vector<int>(2, 0));

    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 2; ++j)
            for (int k = 0; k < 2; ++k)
                r[i][j] = (r[i][j] + a[i][k] * 1LL * b[k][j]) % M;

    return r;
}

vector<vector<int>> matrixPow(long long d)
{
    if (d == 0)
        return {{1, 0}, {0, 1}};

    vector<vector<int>> half = matrixPow(d / 2);
    vector<vector<int>> result = pr(half, half);

    if (d & 1LL)
        result = pr(m, result);

    return result;
}

int main()
{
    cin >> n;

    st = {{1, 0}, {3, 1}};
    m = {{3, 1}, {1, 3}};

    vector<vector<int>> mn = matrixPow(n);
    vector<vector<int>> res = pr(st, mn);

    cout << res[0][0];
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;
using Matrix = vector<vector<int>>;

Matrix multiply(const Matrix& a, const Matrix& b)
{
    Matrix result(2, vector<int>(2, 0));

    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 2; ++j)
            for (int k = 0; k < 2; ++k)
                result[i][j] = (result[i][j] +
                    static_cast<long long>(a[i][k]) * b[k][j]) % MOD;

    return result;
}

Matrix matrixPower(Matrix base, long long exponent)
{
    Matrix result = {{1, 0}, {0, 1}};

    while (exponent > 0)
    {
        if (exponent & 1LL)
            result = multiply(result, base);

        base = multiply(base, base);
        exponent >>= 1;
    }

    return result;
}

int main()
{
    long long n;
    cin >> n;

    Matrix st = {{1, 0}, {3, 1}};
    Matrix m = {{3, 1}, {1, 3}};

    Matrix result = multiply(st, matrixPower(m, n));
    cout << result[0][0];

    return 0;
}

